/**
 * Seasonal Keyword Planner — pure logic (zero imports, zero network, zero DOM).
 *
 * Turns one seed keyword into a 12-month seasonal content plan using a
 * built-in EDITORIAL event bank. This is a planning template, not live
 * data: events and angles are fixed, human-written templates. Nothing is
 * generated by an AI model and no live search-trend data is shown — verify
 * real demand in Google Trends before publishing.
 *
 * Event bank: 36 events x 3 angle templates each (bank size documented in
 * EVENT_BANK / ANGLES_PER_EVENT). Niche tags are plain topic words; an
 * event counts as a "niche match" when any tag appears in the seed keyword
 * (or vice versa). Generic events (no tags) are always included.
 *
 * Determinism: same inputs -> identical outputs. "year" defaults to the
 * current UTC calendar year. Publish-by dates are computed as
 * (first day of the event month) minus leadWeeks, using UTC date math.
 */

export const EVENT_BANK_VERSION = "v1.0.0 (effective 2026-10-01)";
export const ANGLES_PER_EVENT = 3;

export interface SeasonalEvent {
  /** e.g. "Black Friday". */
  name: string;
  /** 1-12. */
  month: number;
  /** Topic words that mark this event as niche-relevant, e.g. ["fitness"]. Empty = generic. */
  nicheTags: string[];
  /** How many weeks before the event month content should be published. */
  leadWeeks: number;
  /** Exactly ANGLES_PER_EVENT templates; use {seed} for the keyword. */
  angles: string[];
}

