const MONTH_NAMES = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

/** True when any niche tag of the event relates to the seed keyword (or vice versa). */
export function nicheMatchesSeed(seed: string, event: SeasonalEvent): boolean {
  const words = seed
    .toLowerCase()
    .split(/[\s\-_.,;:!?()/"'&]+/)
    .filter(Boolean);
  if (event.nicheTags.length === 0) return false;
  return event.nicheTags.some((tag) =>
    words.some((w) => w.includes(tag) || tag.includes(w)),
  );
}

/**
 * Publish-by date: first day of the event month minus leadWeeks,
 * computed with UTC date math. Returns YYYY-MM-DD.
 */
export function publishByDate(year: number, month: number, leadWeeks: number): string {
  const ms = Date.UTC(year, month - 1, 1) - leadWeeks * 7 * 86400000;
  const d = new Date(ms);
  const pad = (n: number): string => String(n).padStart(2, "0");
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
}

/**
 * Run the planner. Values in:
 *   seedKeyword: string (required, 2-100 chars)
 *   year: number        (optional; defaults to current UTC year, must be current year +/- 1)
 *
 * Values out:
 *   seasonalPlan: { columns: string[]; rows: string[][] }
 *   eventBankVersion: string
 */
export function runTool(values: Record<string, unknown>): {
  ok: boolean;
  values?: Record<string, unknown>;
  error?: string;
} {
  const v = values ?? {};

  const seedRaw = v["seedKeyword"];
  const seed = typeof seedRaw === "string" ? seedRaw.trim() : "";
  if (!seed) {
    return { ok: false, error: "Seed keyword is required." };
  }
  if (seed.length < 2 || seed.length > 100) {
    return { ok: false, error: "Seed keyword must be 2-100 characters." };
  }

  const currentYear = new Date().getUTCFullYear();
  let year = currentYear;
  const yearRaw = v["year"];
  if (yearRaw !== undefined && yearRaw !== null && yearRaw !== "") {
    const parsed = typeof yearRaw === "number" ? yearRaw : Number(String(yearRaw).trim());
    if (!Number.isInteger(parsed)) {
      return { ok: false, error: "Year must be a whole number." };
    }
    if (parsed < currentYear - 1 || parsed > currentYear + 1) {
      return {
        ok: false,
        error: `Year must be ${currentYear - 1}, ${currentYear}, or ${currentYear + 1}.`,
      };
    }
    year = parsed;
  }

  const sorted = [...EVENT_BANK].sort((a, b) =>
    a.month === b.month ? (a.name < b.name ? -1 : a.name > b.name ? 1 : 0) : a.month - b.month,
  );

  const columns = ["Month", "Event", "Content angles", "Publish by", "Niche match"];
  const rows: string[][] = sorted.map((event) => {
    const matched = nicheMatchesSeed(seed, event);
    const angles = event.angles.map((t) => t.replace(/\{seed\}/g, seed)).join(" / ");
    return [
      MONTH_NAMES[event.month - 1],
      event.name,
      angles,
      publishByDate(year, event.month, event.leadWeeks),
      matched ? "Yes" : "Generic",
    ];
  });

  return {
    ok: true,
    values: {
      seasonalPlan: { columns, rows },
      eventBankVersion: EVENT_BANK_VERSION,
    },
  };
}
